import numpy as np
import torch as th
import torch.nn as nn
import torch.nn.functional as F

# Excerpt from QDrop/quant/quant_layer.py
def round_ste(x: th.Tensor):
    return (x.round() - x).detach() + x

def lp_loss(pred, tgt, p=2.0, reduction="none"):
    if reduction == "none":
        return (pred - tgt).abs().pow(p).sum(1).mean()
    else:
        return (pred - tgt).abs().pow(p).mean()

class UniformAffineQuantizer(nn.Module):
    def __init__(self, n_bits: int = 8, symmetric: bool = False, channel_wise: bool = False, scale_method: str = "minmax", leaf_param: bool = False, prob: float = 1.0):
        super(UniformAffineQuantizer, self).__init__()
        self.sym = symmetric
        assert 2 <= n_bits <= 8, "bitwidth not supported"
        self.n_bits = n_bits
        self.n_levels = 2**self.n_bits
        self.delta = 1.0
        self.zero_point = 0.0
        self.inited = False # Changed default to False for clarity in calibration
        self.leaf_param = leaf_param
        self.channel_wise = channel_wise
        self.eps = th.tensor(1e-8, dtype=th.float32)
        self.scale_method = scale_method # will be 'mse'
        self.one_side_dist = None
        self.num = 100
        self.is_training = False
        self.prob = prob
        self.timewise_quant_mode = False # Relevant for multi-timestep DMs
        self.fast_mode = False
        self.now_t = None
        self.timestep_params = {}

    def change_timestep(self, t):
        assert self.timewise_quant_mode
        assert type(t) == int
        if self.now_t is not None:
            self.timestep_params[self.now_t] = [
                self.delta,
                self.zero_point,
                self.inited,
            ]
        if t not in self.timestep_params:
            self.timestep_params[t] = [1, 0, False]
        self.delta, self.zero_point, self.inited = self.timestep_params[t]
        self.now_t = t

    def set_inited(self, inited: bool = True):
        self.inited = inited

    def forward(self, x: th.Tensor):
        if self.inited is False:
            self.delta, self.zero_point = self.init_quantization_scale(x.clone().detach(), self.channel_wise)
            self.set_inited(True)

        x_int = round_ste(x / self.delta) + self.zero_point
        x_quant = th.clamp(x_int, 0, self.n_levels - 1)
        x_dequant = (x_quant - self.zero_point) * self.delta
        if self.is_training and self.prob < 1.0:
            x_ans = th.where(th.rand_like(x) < self.prob, x_dequant, x)
        else:
            x_ans = x_dequant
        return x_ans

    def calculate_qparams(self, min_val, max_val):
        quant_min, quant_max = 0, self.n_levels - 1
        min_val_neg = th.min(min_val, th.zeros_like(min_val))
        max_val_pos = th.max(max_val, th.zeros_like(max_val))

        scale = (max_val_pos - min_val_neg) / float(quant_max - quant_min)
        scale = th.max(scale, self.eps)
        zero_point = quant_min - th.round(min_val_neg / scale)
        zero_point = th.clamp(zero_point, quant_min, quant_max)
        return scale, zero_point

    def quantize(self, x: th.Tensor, x_max, x_min):
        delta, zero_point = self.calculate_qparams(x_min, x_max)
        if self.channel_wise:
            new_shape = [1] * len(x.shape)
            new_shape[0] = x.shape[0]
            delta = delta.reshape(new_shape)
            zero_point = zero_point.reshape(new_shape)
        x_int = th.round(x / delta)
        x_quant = th.clamp(x_int + zero_point, 0, self.n_levels - 1)
        x_float_q = (x_quant - zero_point) * delta
        return x_float_q

    def perform_1D_search(self, x):
        if self.channel_wise:
            y = th.flatten(x, 1)
            x_min, x_max = th._aminmax(y, 1)
        else:
            x_min, x_max = th._aminmax(x)
        xrange = th.max(x_min.abs(), x_max)
        best_score = th.zeros_like(x_min) + (1e10)
        best_min = x_min.clone()
        best_max = x_max.clone()

        if not self.channel_wise:
            thres = (xrange / self.num * th.arange(1, self.num + 1, device=x.device))
            new_min = th.zeros_like(thres) if self.one_side_dist == "pos" else -thres
            new_max = th.zeros_like(thres) if self.one_side_dist == "neg" else thres
            quant_min, quant_max = 0, self.n_levels - 1
            scale = (new_max - new_min) / float(quant_max - quant_min)
            scale = th.max(scale, self.eps)
            zero_point = -th.round(new_min / scale)
            zero_point = th.clamp_(zero_point, quant_min, quant_max).view(-1, 1)
            scale = scale.view(-1, 1)

            scores = []
            batch_size = 8 # Batching for memory efficiency
            for i in range(0, self.num, batch_size):
                x_int = (x.view(1, -1) / scale[i : i + batch_size]).round_()
                x_int.clamp_(-zero_point[i : i + batch_size], self.n_levels - 1 - zero_point[i : i + batch_size])
                x_sim = x_int.mul_(scale[i : i + batch_size])
                score = (x_sim.sub_(x.view(1, -1)).abs_().pow_(2.4).mean(1))
                scores.append(score)
                del x_sim
            ind = th.argmin(th.hstack(scores))
            best_min1 = new_min[ind]
            best_max1 = new_max[ind]
            return best_min1, best_max1

        for i in range(1, self.num + 1):
            thres = xrange / self.num * i
            new_min = th.zeros_like(x_min) if self.one_side_dist == "pos" else -thres
            new_max = th.zeros_like(x_max) if self.one_side_dist == "neg" else thres

            x_q = self.quantize(x, new_max, new_min)
            score = self.lp_loss(x, x_q, 2.4)
            best_min = th.where(score < best_score, new_min, best_min)
            best_max = th.where(score < best_score, new_max, best_max)
            best_score = th.min(score, best_score)
        return best_min, best_max

    def perform_2D_search(self, x):
        if self.channel_wise:
            y = th.flatten(x, 1)
            x_min, x_max = th._aminmax(y, 1)
            x_max = th.max(x_max, th.zeros_like(x_max))
            x_min = th.min(x_min, th.zeros_like(x_min))
        else:
            x_min, x_max = th._aminmax(x)
        xrange = x_max - x_min
        best_score = th.zeros_like(x_min) + (1e10)
        best_min = x_min.clone()
        best_max = x_max.clone()
        for i in range(1, self.num + 1):
            tmp_min = th.zeros_like(x_min)
            tmp_max = xrange / self.num * i
            tmp_delta = (tmp_max - tmp_min) / (2**self.n_bits - 1)
            for zp in range(0, self.n_levels):
                new_min = tmp_min - zp * tmp_delta
                new_max = tmp_max - zp * tmp_delta
                x_q = self.quantize(x, new_max, new_min)
                score = self.lp_loss(x, x_q, 2.4)
                best_min = th.where(score < best_score, new_min, best_min)
                best_max = th.where(score < best_score, new_max, best_max)
                best_score = th.min(best_score, score)
        return best_min, best_max

    def get_x_min_x_max(self, x):
        if self.scale_method != "mse":
            raise NotImplementedError
        if self.one_side_dist is None:
            self.one_side_dist = ("pos" if x.min() >= 0.0 else "neg" if x.max() <= 0.0 else "no")
        if (self.one_side_dist != "no" or self.sym):
            best_min, best_max = self.perform_1D_search(x)
        else:
            best_min, best_max = self.perform_2D_search(x)
        return best_min, best_max

    def init_quantization_scale_channel(self, x: th.Tensor):
        with th.no_grad():
            x_min, x_max = self.get_x_min_x_max(x)
            scale, zero_point = self.calculate_qparams(x_min, x_max)
        return scale, zero_point

    def init_quantization_scale(self, x_clone: th.Tensor, channel_wise: bool = False):
        if channel_wise:
            delta, zero_point = self.init_quantization_scale_channel(x_clone)
            new_shape = [1] * len(x_clone.shape)
            new_shape[0] = x_clone.shape[0]
            delta = delta.reshape(new_shape)
            zero_point = zero_point.reshape(new_shape)
        else:
            delta, zero_point = self.init_quantization_scale_channel(x_clone)
        return delta, zero_point

    def bitwidth_refactor(self, refactored_bit: int):
        assert 2 <= refactored_bit <= 32, "bitwidth not supported"
        self.n_bits = refactored_bit
        self.n_levels = 2**self.n_bits

# Excerpt from QDrop/quant/adaptive_rounding.py
class AdaRoundQuantizer(nn.Module):
    def __init__(self, uaq: UniformAffineQuantizer, weight_tensor: th.Tensor, round_mode='learned_round_sigmoid'):
        super(AdaRoundQuantizer, self).__init__()
        self.n_bits = uaq.n_bits
        self.sym = uaq.sym
        self.delta = uaq.delta
        self.zero_point = uaq.zero_point
        self.n_levels = uaq.n_levels
        self.round_mode = round_mode
        self.alpha = None
        self.soft_targets = False
        self.gamma, self.zeta = -0.1, 1.1
        self.beta = 2/3
        self.init_alpha(x=weight_tensor.clone())

    def forward(self, x):
        if self.round_mode == 'nearest':
            x_int = th.round(x / self.delta)
        elif self.round_mode == 'nearest_ste':
            x_int = round_ste(x / self.delta)
        elif self.round_mode == 'learned_hard_sigmoid':
            x_floor = th.floor(x / self.delta)
            if self.soft_targets:
                x_int = x_floor + self.get_soft_targets()
            else:
                x_int = x_floor + (self.alpha >= 0).float()
        else:
            raise ValueError('Wrong rounding mode')

        x_quant = th.clamp(x_int + self.zero_point, 0, self.n_levels - 1)
        x_float_q = (x_quant - self.zero_point) * self.delta

        return x_float_q

    def get_soft_targets(self):
        return th.clamp(th.sigmoid(self.alpha) * (self.zeta - self.gamma) + self.gamma, 0, 1)

    def init_alpha(self, x: th.Tensor):
        x_floor = th.floor(x / self.delta)
        if self.round_mode == 'learned_hard_sigmoid':
            rest = (x / self.delta) - x_floor
            alpha = -th.log((self.zeta - self.gamma) / (rest - self.gamma) - 1)
            self.alpha = nn.Parameter(alpha)
        else:
            raise NotImplementedError

# Excerpt from QDrop/quant/quant_layer.py
class StraightThrough(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, input):
        return input

class QuantModule(nn.Module):
    def __init__(
        self,
        org_module: nn.Module,
        weight_quant_params: dict = {},
        act_quant_params: dict = {},
        disable_act_quant=False,
    ):
        super(QuantModule, self).__init__()
        if isinstance(org_module, nn.Conv2d):
            self.fwd_kwargs = dict(
                stride=org_module.stride,
                padding=org_module.padding,
                dilation=org_module.dilation,
                groups=org_module.groups,
            )
            self.fwd_func = F.conv2d
        else:
            self.fwd_kwargs = dict()
            self.fwd_func = F.linear
        self.weight = org_module.weight
        self.org_weight = org_module.weight.data.clone()
        if org_module.bias is not None:
            self.bias = org_module.bias
            self.org_bias = org_module.bias.data.clone()
        else:
            self.bias = None
            self.org_bias = None
        self.use_weight_quant = False
        self.use_act_quant = False
        self.weight_quantizer = UniformAffineQuantizer(**weight_quant_params)
        self.act_quantizer = UniformAffineQuantizer(**act_quant_params)
        self.activation_function = StraightThrough()
        self.ignore_reconstruction = False
        self.disable_act_quant = disable_act_quant

    def forward(self, input: th.Tensor):
        if self.use_weight_quant:
            weight = self.weight_quantizer(self.weight)
            bias = self.bias
        else:
            weight = self.org_weight
            bias = self.org_bias
        out = self.fwd_func(input, weight, bias, **self.fwd_kwargs)
        out = self.activation_function(out)
        if self.disable_act_quant:
            return out
        if self.use_act_quant:
            out = self.act_quantizer(out)
        return out

    def set_quant_state(self, weight_quant: bool = False, act_quant: bool = False):
        self.use_weight_quant = weight_quant
        self.use_act_quant = act_quant

# Excerpt from QDrop/quant/quant_block.py
class BaseQuantBlock(nn.Module):
    def __init__(self):
        super().__init__()
        self.use_weight_quant = False
        self.use_act_quant = False
        self.ignore_reconstruction = False

    def set_quant_state(self, weight_quant: bool = False, act_quant: bool = False):
        self.use_weight_quant = weight_quant
        self.use_act_quant = act_quant
        for m in self.modules():
            if isinstance(m, QuantModule):
                m.set_quant_state(weight_quant, act_quant)

