    raise NotImplementedError # This function is a placeholder for the actual data capturing mechanism

def set_weight_quantize_params(model):
    for name, module in model.named_modules():
        if isinstance(module, QuantModule):
            module.weight_quantizer.set_inited(False)
            module.weight_quantizer(module.weight)
            module.weight_quantizer.set_inited(True)

def weight_get_quant_state(order, act_quant):
    if not act_quant:
        return True, False
    if order == "before":
        weight_quant, act_quant = True, True
    elif order == "after":
        weight_quant, act_quant = True, False
    elif order == "together":
        weight_quant, act_quant = True, True
    else:
        raise NotImplementedError
    return weight_quant, act_quant

# Excerpt from QDrop/quant/set_act_quantize_params.py
def set_act_quantize_params(module: nn.Module, cali_data, awq: bool = False, order: str = "before", batch_size: int = 256):
    weight_quant, act_quant = act_get_quant_state(order, awq)
    module.set_quant_state(weight_quant, act_quant)

    for t in module.modules():
        if isinstance(t, (QuantModule, BaseQuantBlock)):
            t.act_quantizer.set_inited(False)

    if not isinstance(cali_data, (tuple, list)):
        batch_size = min(batch_size, cali_data.size(0))
        with th.no_grad():
            for i in range(int(cali_data.size(0) / batch_size)):
                module(cali_data[i * batch_size : (i + 1) * batch_size].cuda())
    else:
        batch_size = min(batch_size, cali_data[0].size(0))
        with th.no_grad():
            for i in range(int(cali_data[0].size(0) / batch_size)):
                module(*[_[i * batch_size : (i + 1) * batch_size].cuda() for _ in cali_data])
    for t in module.modules():
        if isinstance(t, (QuantModule, BaseQuantBlock)):
            t.act_quantizer.set_inited(True)

def act_get_quant_state(order, awq):
    if order == "before":
        weight_quant, act_quant = False, True
    elif order == "after":
        weight_quant, act_quant = awq, True
    elif order == "together":
        weight_quant, act_quant = True, True
    else:
        raise NotImplementedError
    return weight_quant, act_quant

# Excerpt from QDrop/quant/block_recon.py and QDrop/quant/layer_recon.py
class LinearTempDecay:
    def __init__(self, t_max: int, rel_start_decay: float = 0.2, start_b: int = 10, end_b: int = 2):
        self.t_max = t_max
        self.start_decay = rel_start_decay * t_max
        self.start_b = start_b
        self.end_b = end_b

    def __call__(self, t):
        if t < self.start_decay:
            return self.start_b
        else:
            rel_t = (t - self.start_decay) / (self.t_max - self.start_decay)
            return self.end_b + (self.start_b - self.end_b) * max(0.0, (1 - rel_t))

class LossFunction:
    def __init__(self, block_or_layer: nn.Module, round_loss: str = 'relaxation', weight: float = 1., rec_loss: str = 'mse', max_count: int = 2000, b_range: tuple = (10, 2), decay_start: float = 0.0, warmup: float = 0.0, p: float = 2.):
        self.block_or_layer = block_or_layer
        self.round_loss = round_loss
        self.weight = weight
        self.rec_loss = rec_loss
        self.loss_start = max_count * warmup
        self.p = p
        self.temp_decay = LinearTempDecay(max_count, rel_start_decay=warmup + (1 - warmup) * decay_start, start_b=b_range[0], end_b=b_range[1])
        self.count = 0

    def __call__(self, pred, tgt, grad=None):
        self.count += 1
        if self.rec_loss == 'mse':
            rec_loss = lp_loss(pred, tgt, p=self.p)
        else:
            raise ValueError('Not supported reconstruction loss function: {}'.format(self.rec_loss))

        b = self.temp_decay(self.count)
        if self.count < self.loss_start or self.round_loss == 'none':
            b = round_loss = 0
        elif self.round_loss == 'relaxation':
            round_loss = 0
            # Handles both QuantModule and BaseQuantBlock cases
            if isinstance(self.block_or_layer, QuantModule):
                 round_vals = self.block_or_layer.weight_quantizer.get_soft_targets()
                 round_loss += self.weight * (1 - ((round_vals - .5).abs() * 2).pow(b)).sum()
            elif isinstance(self.block_or_layer, BaseQuantBlock):
                for name, module in self.block_or_layer.named_modules():
                    if isinstance(module, QuantModule):
                        round_vals = module.weight_quantizer.get_soft_targets()
                        round_loss += self.weight * (1 - ((round_vals - .5).abs() * 2).pow(b)).sum()
        else:
            raise NotImplementedError

        total_loss = rec_loss + round_loss
        return total_loss

# Excerpt from QDrop/quant/block_recon.py
def block_reconstruction(model: QuantModel, block: BaseQuantBlock, cali_data: th.Tensor,
                         batch_size: int = 32, iters: int = 20000, weight: float = 0.01, opt_mode: str = 'mse',
                         act_quant: bool = False, b_range: tuple = (20, 2),
                         warmup: float = 0.0, p: float = 2.0, lr: float = 4e-5, wwq: bool = True, waq: bool = True,
                         order: str = 'together', input_prob: float = 1.0, keep_gpu: bool = True):
    cached_inps, cached_outs = get_init(model, block, cali_data, wq=wwq, aq=waq, batch_size=batch_size, input_prob=True, keep_gpu=keep_gpu)
    if act_quant and order == 'together':
        set_act_quantize_params(block, cali_data=cached_inps[0][:min(256, cached_inps[0].size(0))], awq=True, order=order)
    cur_weight, cur_act = weight_get_quant_state(order, act_quant)
    block.set_quant_state(cur_weight, cur_act)

    round_mode = 'learned_hard_sigmoid'
    w_para, a_para = [], []
    for module in block.modules():
        if isinstance(module, QuantModule):
            module.weight_quantizer = AdaRoundQuantizer(uaq=module.weight_quantizer, round_mode=round_mode, weight_tensor=module.org_weight.data)
            module.weight_quantizer.soft_targets = True
            w_para += [module.weight_quantizer.alpha]
        if isinstance(module, (QuantModule, BaseQuantBlock)):
            if act_quant and order == 'together' and module.act_quantizer.delta is not None:
                module.act_quantizer.delta = th.nn.Parameter(th.tensor(module.act_quantizer.delta))
                a_para += [module.act_quantizer.delta]
            module.act_quantizer.is_training = True

    w_opt = th.optim.Adam(w_para) if len(w_para) != 0 else None
    a_opt = th.optim.Adam(a_para, lr=lr) if len(a_para) != 0 else None
    a_scheduler = th.optim.lr_scheduler.CosineAnnealingLR(a_opt, T_max=iters, eta_min=0.) if a_opt else None

    loss_func = LossFunction(block, round_loss='relaxation', weight=weight, max_count=iters, rec_loss=opt_mode, b_range=b_range, decay_start=0, warmup=warmup, p=p)
    device = 'cuda'
    sz = cached_inps[0].size(0)
    for i in range(iters):
        idx = th.randint(0, sz, (batch_size,))
        cur_inp, cur_sym = cached_inps[0][idx].to(device), cached_inps[1][idx].to(device)
        if input_prob < 1.0:
            cur_inp = th.where(th.rand_like(cur_inp) < input_prob, cur_inp, cur_sym)
        cur_out = cached_outs[idx].to(device)
        if w_opt: w_opt.zero_grad()
        if a_opt: a_opt.zero_grad()
        out_quant = block(cur_inp)
        err = loss_func(out_quant, cur_out)
        err.backward(retain_graph=True)
        if w_opt: w_opt.step()
        if a_opt: a_opt.step()
        if a_scheduler: a_scheduler.step()
    th.cuda.empty_cache()

    for module in block.modules():
        if isinstance(module, QuantModule):
            module.weight_quantizer.soft_targets = False
        if isinstance(module, (QuantModule, BaseQuantBlock)):
            module.act_quantizer.is_training = False
    if act_quant and order == 'after' and waq:
        set_act_quantize_params(block, cached_inps[0], awq=True, order=order)

# Excerpt from QDrop/quant/layer_recon.py
def layer_reconstruction(model: QuantModel, layer: QuantModule, cali_data: th.Tensor,
                         batch_size: int = 32, iters: int = 20000, weight: float = 0.001, opt_mode: str = 'mse',
                         act_quant: bool = False, b_range: tuple = (20, 2),
                         warmup: float = 0.0, p: float = 2.0, lr: float = 4e-5, wwq: bool = True, waq: bool = True,
                         order: str = 'together', input_prob: float = 1.0, keep_gpu: bool = True):
    cached_inps, cached_outs = get_init(model, layer, cali_data, wq=wwq, aq=waq, batch_size=batch_size, input_prob=True, keep_gpu=keep_gpu)
    if act_quant and order == 'together':
        set_act_quantize_params(layer, cali_data=cached_inps[0][:min(256, cached_inps[0].size(0))], awq=True, order=order)

    cur_weight, cur_act = weight_get_quant_state(order, act_quant)
    layer.set_quant_state(cur_weight, cur_act)

    round_mode = 'learned_hard_sigmoid'
    w_para, a_para = [], []

    layer.weight_quantizer = AdaRoundQuantizer(uaq=layer.weight_quantizer, round_mode=round_mode, weight_tensor=layer.org_weight.data)
    layer.weight_quantizer.soft_targets = True
    w_para += [layer.weight_quantizer.alpha]

    if act_quant and order == 'together' and layer.act_quantizer.delta is not None:
        layer.act_quantizer.delta = th.nn.Parameter(th.tensor(layer.act_quantizer.delta))
        a_para += [layer.act_quantizer.delta]
    layer.act_quantizer.is_training = True

    w_opt = th.optim.Adam(w_para) if len(w_para) != 0 else None
    a_opt = th.optim.Adam(a_para, lr=lr) if len(a_para) != 0 else None
    a_scheduler = th.optim.lr_scheduler.CosineAnnealingLR(a_opt, T_max=iters, eta_min=0.) if a_opt else None

    loss_func = LossFunction(layer, round_loss='relaxation', weight=weight, max_count=iters, rec_loss=opt_mode, b_range=b_range, decay_start=0, warmup=warmup, p=p)
    device = 'cuda'
    sz = cached_inps[0].size(0)
    for i in range(iters):
        idx = th.randint(0, sz, (batch_size,))
        cur_inp, cur_sym = cached_inps[0][idx].to(device), cached_inps[1][idx].to(device)
        if input_prob < 1.0:
            cur_inp = th.where(th.rand_like(cur_inp) < input_prob, cur_inp, cur_sym)
        cur_out = cached_outs[idx].to(device)

        if w_opt: w_opt.zero_grad()
        if a_opt: a_opt.zero_grad()
        out_quant = layer(cur_inp)
        err = loss_func(out_quant, cur_out)
        err.backward(retain_graph=True)
        if w_opt: w_opt.step()
        if a_opt: a_opt.step()
        if a_scheduler: a_scheduler.step()
    th.cuda.empty_cache()

    layer.weight_quantizer.soft_targets = False
    layer.act_quantizer.is_training = False
    if act_quant and order == 'after' and waq:
        set_act_quantize_params(layer, cached_inps[0], awq=True, order=order)

# Excerpt from improved-diffusion/scripts/quant_image_sample.py
def generate_t(args, t_mode, num_samples, diffusion, device):
    if t_mode == "normal":
        shape = th.Tensor(num_samples)
        # Samples time-steps from a normal distribution and clamps them
        normal_val = th.nn.init.normal_(shape, mean=args.calib_t_mode_normal_mean, std=args.calib_t_mode_normal_std)*diffusion.num_timesteps
        t = normal_val.clone().type(th.int).to(device=device)
    # ... (other t_mode options)
    else:
        raise NotImplementedError("Unsupported t_mode for calibration")
    return t.clamp(0, diffusion.num_timesteps - 1)

def random_calib_data_generator(shape, num_samples, device, t_mode, diffusion, class_cond=True):
    calib_data = []
    for batch in range(num_samples):
        img = th.randn(*shape, device=device)
        calib_data.append(img)
    t = generate_t(args, t_mode, num_samples, diffusion, device) # Using `args` for mean/std
    t = diffusion._scale_timesteps(t)
    if class_cond:
        cls = th.tensor([1] * num_samples, device=device).long()
        return th.cat(calib_data, dim=0), t, cls
    else:
        return th.cat(calib_data, dim=0), t

def raw_calib_data_generator(args, num_samples, device, t_mode, diffusion, class_cond=True):
    # ... (code to load data from args.data_dir)
    loader = load_data(
        data_dir=args.data_dir,
        batch_size=num_samples,
        image_size=args.image_size,
        class_cond=class_cond,
    )
    calib_data, cls = next(loader)
    calib_data = calib_data.to(device)
    t = generate_t(args, t_mode, num_samples, diffusion, device) # Using `args` for mean/std
    t = diffusion._scale_timesteps(t)
    if class_cond:
        return calib_data, t, cls.to(device)
    else:
        return calib_data, t

def forward_t_calib_data_generator(args, num_samples, device, t_mode, diffusion, class_cond=True):
    # ... (code to load raw data and forward it to time t)
    loader = load_data(
        data_dir=args.data_dir,
        batch_size=num_samples,
        image_size=args.image_size,
        class_cond=class_cond,
    )
    calib_data, cls = next(loader)
    calib_data = calib_data.to(device)
    t = generate_t(args, t_mode, num_samples, diffusion, device).long()
    x_t = diffusion.q_sample(calib_data, t)
    t = diffusion._scale_timesteps(t)
    if class_cond:
        return x_t, t, cls.to(device)
    else:
        return x_t, t

def backward_t_calib_data_generator(model, args, num_samples, device, t_mode, diffusion, class_cond=True):
    # ... (code to sample from diffusion model up to time t)
    model_kwargs = {}
    if class_cond:
        cls = th.tensor([1] * num_samples, device=device).long()
        model_kwargs["y"] = cls
    loop_fn = (
        diffusion.ddim_sample_loop_progressive
        if args.use_ddim
        else diffusion.p_sample_loop_progressive
    )
    t_indices = generate_t(args, t_mode, num_samples, diffusion, device).long() # Original t values
    calib_data = None
    for now_rt, sample_t_dict in enumerate(
        loop_fn(
            model,
            (num_samples, 3, args.image_size, args.image_size),
            clip_denoised=args.clip_denoised,
            model_kwargs=model_kwargs,
            device=device,
        )
    ):
        sample_t = sample_t_dict["sample"]
        if calib_data is None:
            calib_data = th.zeros_like(sample_t)
        # Select samples at their specific t_indices
        mask = t_indices == (diffusion.num_timesteps - 1 - now_rt) # Adjust now_rt to match t_indices from generate_t
        if mask.any():
            calib_data[mask] = sample_t[mask] # Use direct assignment with mask

    calib_data = calib_data.to(device)
    t = diffusion._scale_timesteps(t_indices) # Scale the original t_indices
    if class_cond:
        return calib_data, t, cls.to(device)
    else:
        return calib_data, t

def quant_model(args, model, diffusion):
    wq_params = {
        "n_bits": args.n_bits_w,
        "channel_wise": args.channel_wise,
        "scale_method": args.init_wmode,
        "symmetric": True,
    }
    aq_params = {
        "n_bits": args.n_bits_a,
        "channel_wise": False,
        "scale_method": args.init_amode,
        "leaf_param": True,
        "prob": args.prob,
        "symmetric": True,
    }

    qnn = QuantModel(
        model=model, weight_quant_params=wq_params, act_quant_params=aq_params
    )
    qnn.cuda()
    qnn.eval()
    if not args.disable_8bit_head_stem:
        qnn.set_first_last_layer_to_8bit()

    qnn.disable_network_output_quantization()

    # Select calibration data generation strategy
    if args.calib_im_mode == "random":
        cali_data = random_calib_data_generator(
            [1, 3, args.image_size, args.image_size],
            args.calib_num_samples,
            "cuda",
            args.calib_t_mode,
            diffusion,
            args.class_cond,
        )
    elif args.calib_im_mode == "raw":
        cali_data = raw_calib_data_generator(
            args,
            args.calib_num_samples,
            "cuda",
            args.calib_t_mode,
            diffusion,
            args.class_cond,
        )
    elif args.calib_im_mode == "raw_forward_t":
        cali_data = forward_t_calib_data_generator(
            args,
            args.calib_num_samples,
            "cuda",
            args.calib_t_mode,
            diffusion,
            args.class_cond,
        )
    elif args.calib_im_mode == "noise_backward_t":
        # Special case: needs original model for backward sampling
        cali_data = backward_t_calib_data_generator(
            model,
            args,
            args.calib_num_samples,
            "cuda",
            args.calib_t_mode,
            diffusion,
            args.class_cond,
        )
    else:
        raise NotImplementedError

    # Calibration process starts
    if args.act_quant and args.order == "before" and args.awq is False:
        set_act_quantize_params(
            qnn, cali_data=cali_data, awq=args.awq, order=args.order
        )

    set_weight_quantize_params(qnn)

    if not args.use_adaround:
        set_act_quantize_params(
            qnn, cali_data=cali_data, awq=args.awq, order=args.order
        )
        qnn.set_quant_state(weight_quant=True, act_quant=args.act_quant)
        return qnn
    else:
        def set_weight_act_quantize_params(module):
            if isinstance(module, QuantModule):
                layer_reconstruction(qnn, module, **kwargs)
            elif isinstance(module, BaseQuantBlock):
                block_reconstruction(qnn, module, **kwargs)
            else:
                raise NotImplementedError

        def recon_model(model: nn.Module):
            for name, module in model.named_children():
                if isinstance(module, QuantModule):
                    set_weight_act_quantize_params(module)
                elif isinstance(module, BaseQuantBlock):
                    set_weight_act_quantize_params(module)
                else:
                    recon_model(module)

        kwargs = dict(
            cali_data=cali_data,
            iters=args.iters_w,
            weight=args.weight,
            b_range=(args.b_start, args.b_end),
            warmup=args.warmup,
            opt_mode="mse",
            wwq=args.wwq,
            waq=args.waq,
            order=args.order,
            act_quant=args.act_quant,
            lr=args.lr,
            input_prob=args.input_prob,
            keep_gpu=not args.keep_cpu,
        )
        recon_model(qnn)

        if args.act_quant and args.order == "after" and args.waq is False:
            set_act_quantize_params(
                qnn, cali_data=cali_data, awq=args.awq, order=args.order
            )

        qnn.set_quant_state(weight_quant=True, act_quant=args.act_quant)
        return qnn

from typing import NamedTuple, Any, Union
from collections.abc import Sequence, Callable, Iterable, Iterator
from contextlib import contextmanager
import operator as op
import numpy as np
from functools import partial, lru_cache
import itertools as it
from collections import defaultdict
