def _vjp(fun: Callable, *primals, has_aux=False):
  primals_flat, in_tree = tree_flatten(primals)
  if not has_aux:
    flat_fun, out_tree = flatten_fun(fun, in_tree)
    out_primals, vjp_fun = (lambda f, p: (p, lambda ct: f(ct)))(flat_fun(*primals_flat), primals_flat) # Simplified
    out_tree = out_tree()
  else:
    flat_fun, out_aux_trees = flatten_fun(fun, in_tree)
    out_primals, vjp_fun, aux = (lambda f, p: (p, lambda ct: f(ct), {}))(flat_fun(*primals_flat), primals_flat) # Simplified
    out_tree, aux_tree = out_aux_trees()
  out_primal_avals = map(get_aval, out_primals) # Simplified
  out_primal_py = tree_unflatten(out_tree, out_primals)
  vjp_py = partial(_vjp_pullback_wrapper, fun.__name__, out_primal_avals, (out_tree, in_tree), vjp_fun)
